Section NEST_BRANCH.
Variables (T : Type) (rec : mstate -> Z -> Z -> (mstate -> Z -> M T) -> M T -> M T) (F N : nat).
Variables (idle : list aptr) (st0 st1 : mstate) (L0 L1 : mled) (BL : list blk) (LS1 : lhead -> list aptr).
Variables (m : aptr) (sc req cnt : Z) (k : mstate -> optr -> M T) (bail : M T) (Post : mled -> T -> Prop).
Hypothesis REC : ltac2:(zQ "10!njb@6$0?1T?3rec?2sc?1F?1N?4Post").
Hypothesis INV1 : ltac2:(zQ "40!nh5!hs7!ige!rc@5$1@1$2@3$0$3?1m?4idle?3st1?2L1?2BL?3LS1").
Hypothesis NIm : ltac2:(zQ "30!nhb!rc!nj5@1$0@3$2$1?1m?4idle").
Hypothesis ND : ltac2:(zQ "20!rc!lj9@2$1$0?4idle").
Hypothesis TF1 : ltac2:(zQ "10!iv1@1$0?3st1").
Hypothesis Hsc : ltac2:(zQ "30!hj1!hr7!iia@2$0@2$1Z?2sc@2$2?2sc+j0").
Hypothesis Hreq : 0 <= req.
Hypothesis Hfit : ltac2:(zQ "60!jpa!jpf!jtc!ju9!hr7!jv0@2$4@2$3?3req$0@2$5$1@1$2?2sc").
Hypothesis HA1 : ltac2:(zQ "40!hp6!hjc!j7!ii3>3sc'$2@3$1$3@2$0?3st1^1@2$0?3st0^1").
Hypothesis HA0 : ltac2:(zQ "50!kj0!hjc!hp6!rc!ii3@3$1$4@2$2?3st0?2sc@1$0$3").
Hypothesis HL1 : ltac2:(zQ "40!hrd!h8!hjc!jq6@3$2@1$1$3@1$0?2L1@1$0?2L0").
Hypothesis HG1 : ltac2:(zQ "10!jp4@2$0?3st0?3st1").
Hypothesis HAR1 : ltac2:(zQ "10!jk1@4$0?1N?2BL?3st0?3st1").   (* [comment removed for export] *)
Hypothesis HLEN : ltac2:(zQ "50!mue!kr0!ksa!ku5!rc@2$3@2$2@1$0@2$1$4?4idle?1F?1N").   (* [comment removed for export] *)
Hypothesis NEST : ltac2:(zQ "40!lk2!lu5!hjc!lv5@3$2$0@2$3?2sc?3cnt$1").
Hypothesis HK : ltac2:(zQ "80!h8!n7!kq7!mv1!rc!hh5!s3!ii3>3st2$6>2go$7>2L2$1>3LS2>0$5@1$0$4>0@b$3?1N?4idle?2sc?3req?3st0?2L0?2BL^4^3^2^1@4$2?1T^3@2?1k^5^4?4Post").
Let size := UNIT * size_class sc.
Let j := size_to_class (UNIT + cnt * size - IB).

Theorem ag_nest_ft :
  ftree L1 (rec st1 j (UNIT + cnt * size - IB) (fun st2 idx =>
     if idx <? 0 then free_meta m st2 (fun st3 => k st3 None) bail
     else match active st2 j with
          | None => SVis (EUndef UBadPtr) (fun _ => bail)
          | Some g => ag_tail full_lay (upd_meta m (m_set_maplen 0) (nest_layout st2 g idx j size cnt)) sc m (slot_of st2 g idx) cnt (cnt - 1) k
